import{_ as t,g as a,e as s,a4 as n}from"./chunks/framework.CEYJDsBW.js";const u=JSON.parse('{"title":"Previewing NBT and SNBT in Body Text","description":"","frontmatter":{},"headers":[],"relativePath":"en/ageratum/26.1/packs/structures.md","filePath":"en/ageratum/26.1/packs/structures.md"}'),d={name:"en/ageratum/26.1/packs/structures.md"};function o(r,e,i,c,p,l){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="previewing-nbt-and-snbt-in-body-text" tabindex="-1">Previewing NBT and SNBT in Body Text <a class="header-anchor" href="#previewing-nbt-and-snbt-in-body-text" aria-label="Permalink to &quot;Previewing NBT and SNBT in Body Text&quot;">​</a></h1><p>Create <code>repair.md</code> and <code>stand.snbt</code> side by side in <code>assets/workshop/ageratum/en_us/maintenance/</code>. The page only needs to reference the file in the same directory.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Display Stand Base</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;structure id=&quot;stand.snbt&quot;/&gt;</span></span></code></pre></div><p><code>stand.snbt</code> can start as a complete single-block structure.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  DataVersion: 4790,</span></span>
<span class="line"><span>  size: [1, 1, 1],</span></span>
<span class="line"><span>  palette: [{Name: &quot;minecraft:anvil&quot;}],</span></span>
<span class="line"><span>  blocks: [{pos: [0, 0, 0], state: 0}],</span></span>
<span class="line"><span>  entities: []</span></span>
<span class="line"><span>}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td>Tag attributes <code>id</code>, <code>path</code></td><td>Path string</td><td>At least one is required; <code>id</code> takes precedence. Relative paths resolve from the current Markdown file&#39;s directory.</td></tr><tr><td><code>size</code></td><td>List of three integers</td><td>Structure dimensions along X, Y, Z, recorded in that order.</td></tr><tr><td><code>palette</code> or <code>palettes</code></td><td>List of block states or list of palette lists</td><td>At least one palette is required. States use <code>Name</code> and an optional <code>Properties</code> string map.</td></tr><tr><td><code>blocks</code></td><td>List of compounds</td><td>Each entry has a 3-integer <code>pos</code> and palette index <code>state</code>. Block entity data can be placed in <code>nbt</code> on that entry.</td></tr><tr><td><code>entities</code></td><td>List of compounds</td><td>Optional. No entities in this example, so an empty list is written explicitly.</td></tr><tr><td><code>DataVersion</code></td><td>Integer</td><td>Records the structure&#39;s data version. Keeping the game-exported value is recommended.</td></tr></tbody></table><p>When specifying a namespace, use the full resource manager path, such as <code>workshop:ageratum/en_us/maintenance/stand.snbt</code>. If the extension is omitted, it tries the raw path first, then <code>.nbt</code> and <code>.snbt</code>. The component detects compressed NBT by its gzip header; otherwise it tries text SNBT first and then the alternate decoder. The text size limit is 8 MiB. For documentation previews only, SNBT is convenient for version control and manual review. <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDNBTStructureComponent.java" target="_blank" rel="noreferrer">Preview reading &amp; format conversion</a></p><p>When the client cannot find a direct resource, it also queries the mod classloader for built-in NBT and SNBT under <code>data/&lt;namespace&gt;/structure/</code> and <code>structures/</code>. This fallback only checks the classpath; for standalone previews use <code>assets</code>, as world-enabled server data packs do not enter this client classloader. <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDNBTStructureComponent.java" target="_blank" rel="noreferrer">Path resolution</a></p>`,8)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
